import { readFileSync } from 'node:fs';

const fixtureModel = { provider: 'fixture', id: 'model', name: 'fixture-model', contextWindow: 32000, maxTokens: 4096, reasoning: true };

// One model, or the `models` a test wrote to `models.json` in the agent folder.
export class ModelRuntime {
  static async create({ modelsPath } = {}) { return new ModelRuntime(modelsPath); }
  constructor(modelsPath) { this.modelsPath = modelsPath; }
  async getAvailable() {
    try { return JSON.parse(readFileSync(this.modelsPath, 'utf8')).models; }
    catch { return [fixtureModel]; }
  }
  async refresh() {}
  getProviders() { return [{ id: 'fixture', name: 'Fixture', auth: { apiKey: true } }]; }
}
